struct ScenarioMessageLayout {
    ::cw::lib::String wrapped;
    ::cw::lib::ui::FontStyle font;
};

ScenarioMessageLayout scenario_message_layout(const ::cw::lib::String& text,
                                              I logical_width, I reserved_width,
                                              I supplied_pixel_budget = -1)
{
    // Python の二つの _resize メソッドに合わせ、ピクセル上限と設定した dlgmsg
    // の get_wxfont(15) の寸法を同じ単位で扱う。 特に wx の 1px
    // 調整は拡縮後に適用する。2 倍なら 14×2 ではなく 30-1 とする。
    const auto font = ::cw::lib::ui::configured_wx_font("dlgmsg",15);
    const auto scale = std::max<::cw::lib::Real>(1.0,::cw::g_UP_WIN);
    const I pixel_width = supplied_pixel_budget >= 0 ? std::max<I>(1,supplied_pixel_budget)
        : std::max<I>(1,static_cast<I>(std::lround(
            std::max<I>(1,logical_width-reserved_width)*scale)));
    auto metrics = std::make_shared<::cw::imageretouch::Font>();
    metrics->initialize_wx(font.face,-font.pixels,font.bold,font.italic);
    ::cw::lib::Callback extent = [metrics](const ::cw::lib::Arguments& args,
                                      const ::cw::lib::KeywordArguments&) {
        const auto& value = std::get<::cw::lib::String>(args.at(0).storage());
        // wx.GetTextExtent は文字の送り幅を返し、画像中の実際に描かれた部分の幅とは異なる。
        return ::cw::lib::Value(value.empty() ? I{0} :
            std::get<0>(metrics->wx_text_extent(value)));
    };
    return {::cw::util::wordwrap(text,pixel_width,extent,{},{},nullptr),font};
}

I scenario_message_line_height(const ::cw::lib::ui::FontStyle& style)
{
    ::cw::imageretouch::Font font;
    font.initialize_wx(style.face,-style.pixels,style.bold,style.italic);
    return std::max<I>(1,static_cast<I>(std::ceil(font.get_linesize()/std::max(1.0,::cw::g_UP_WIN))));
}

I scenario_message_lines(const ::cw::lib::String& wrapped)
{
    return 1+static_cast<I>(std::count(wrapped.begin(),wrapped.end(),'\n'));
}

::cw::lib::String scenario_directory_caption(const ::cw::lib::String& path)
{
    auto name=path_utf8(fs::u8path(path).filename());
    if(name.empty())name=path;
    // 移植用ホストでも、元の Windows ショートカットの見出しを一
    // 貫して表示する。 プラットフォーム固有なのは参照先の解決だけとし、
    // ツリーの親子関係・選択・インストールには元の別名パスを保持する。
    if(name.size()>=4 && ::cw::lib::encoding::python_lower(name.substr(name.size()-4))==".lnk")
        name.resize(name.size()-4);
    return name;
}

::cw::lib::String overwrite_display_path(const ::cw::lib::String& path)
{
    const auto relative = ::cw::util::relpath(path, path_utf8(fs::absolute(".")));
    auto display = ::cw::util::join_paths({relative});
    // Py と同様、作業ディレクトリー外の項目はフルパスを表示する。別ドラ
    // イブへの relpath も元のパスに戻す。 これは表示だけの処理
    // であり、行の識別と置き換え先の出力には常に元のフルパスを保持する。
    if (display.starts_with("../")) display = ::cw::util::join_paths({path});
    return display;
}

