std::vector<::cw::lib::String> get_dpaths(::cw::lib::String arg_dpath)
{
    namespace fs=std::filesystem;
    std::vector<::cw::lib::String> result;
    const auto append = [&](const ::cw::lib::String& p) {
        if(is_listitem(p)&&!::cw::scenariodb::is_scenario(p)) result.push_back(p);
    };
    try {
        const auto target = linktarget_or_self(std::move(arg_dpath));
        if (::cw::util::path_is_directory(target)) {
            if (::cardwirth::platform::is_mounted_user_path(fs::u8path(target))) {
                if (const auto entries = ::cardwirth::platform::list_mounted_user_path(fs::u8path(target), true))
                    // Python と同様、os.listdir が返す名前を要求ディレクトリ
                    // ーへ結合する。 ストレージは相対パスの要求でも絶対パスを返す場合がある。
                    for (const auto& entry : *entries) append(path_utf8(fs::u8path(target) / entry.path.filename()));
            } else {
                // Python と同様、子の調査を始める前に os.listdir の列挙を完了する。
                std::vector<fs::path> children;
                for (const auto& entry : fs::directory_iterator(fs::u8path(target)))
                    children.push_back(entry.path());
                for (const auto& child : children) append(path_utf8(child));
            }
        }
    } catch (const std::exception&) {
        // Python と同様、列挙や子の調査の失敗をログに残し、それ
        // までに集めた項目を返す。 選択画面を処理中のままにしない。
        ::cw::util::print_ex(std::nullopt);
    }
    // Py の sort_by_filename と同様、フルパスを比較し、同じキーの順序を維持する。
    // Windows の StrCmpLogicalW による大文字小文字・ゼロ埋めの同順位も含める。
    std::stable_sort(result.begin(), result.end(), [](const auto& a, const auto& b) {
        return ::cw::util::sort_by_filename_cmp_fname(a, b) < 0;
    });
    return result;
}

bool is_listitem(::cw::lib::String arg_path)
{
    arg_path = linktarget_or_self(std::move(arg_path));
    return ::cw::util::path_is_directory(arg_path)||::cw::scenariodb::is_scenario(arg_path);
}

std::tuple<HeaderBuckets, FileBuckets> to_scenarioheaders(std::vector<::cw::lib::String> arg_paths, std::shared_ptr<::cw::scenariodb::Scenariodb> arg_db, ::cw::lib::String arg_skintype, bool arg_link)
{
    namespace fs = std::filesystem;
    HeaderBuckets headers;
    FileBuckets files;
    std::set<std::pair<::cw::lib::String, ::cw::lib::String>> known;
    if (arg_paths.empty()) return {std::move(headers), std::move(files)};

    fs::path first = fs::u8path(arg_paths.front());
    std::error_code ec;
    if (::cw::util::path_is_file(path_utf8(first))) {
        auto extension = first.extension().generic_string();
        std::transform(extension.begin(), extension.end(), extension.begin(),
                       [](unsigned char ch) { return static_cast<char>(std::tolower(ch)); });
        if (extension == ".xml" || extension == ".wsm") {
            arg_paths.assign(1, path_utf8(first.parent_path()));
            first = fs::u8path(arg_paths.front());
        }
    }
    const fs::path allparent = first.parent_path();

    auto parent_key = [&](const fs::path& parent) -> BucketKey {
        auto hparent=::cw::util::relpath(path_utf8(parent),path_utf8(allparent));
        if (hparent.starts_with("../") || hparent.starts_with("..\\")) hparent.clear();
        return {path_utf8(parent), std::move(hparent)};
    };

    std::function<bool(const fs::path&, const fs::path&, FileBuckets&)> recurse;
    recurse = [&](const fs::path& parent, const fs::path& path,
                  FileBuckets& pending_files) -> bool {
#ifdef _WIN32
        if (!arg_link) {
            auto lowered = path_utf8(path);
            std::transform(lowered.begin(), lowered.end(), lowered.begin(),
                           [](unsigned char ch) { return static_cast<char>(std::tolower(ch)); });
            if (lowered.size() >= 4 && lowered.substr(lowered.size() - 4) == ".lnk") return false;
        }
#endif
        const auto key = parent_key(parent);
        if (::cw::scenariodb::is_scenario(path_utf8(path))) {
            if (!arg_db) throw std::logic_error("Scenario header lookup requires database");
            auto header = arg_db->search_path(path_utf8(path), arg_skintype);
            if (!header || !*header) return false;
            auto* name = std::get_if<::cw::lib::String>(&(*header)->m_name.storage());
            auto* author = std::get_if<::cw::lib::String>(&(*header)->m_author.storage());
            const auto identity = std::make_pair(
                name ? *name : ::cw::lib::String{},
                author ? *author : ::cw::lib::String{});
            if (!known.insert(identity).second) return false;
            headers[key].push_back(*header);
            return true;
        }

        if (!storage_path_exists(path)) return false;
        if (storage_path_is_directory(path)) {
            bool contains_scenario = false;
            bool has_children = false;
            std::vector<fs::path> children;
            if(::cardwirth::platform::is_mounted_user_path(path)) {
                const auto entries=::cardwirth::platform::list_mounted_user_path(path,true);
                if (!entries) throw std::runtime_error("Cannot enumerate scenario directory");
                for(const auto& entry:*entries)children.push_back(path/entry.path.filename());
            } else for (const auto& entry:fs::directory_iterator(path)) children.push_back(entry.path());
            for(const auto& child:children) {
                has_children = true;
                // bitwise-or相当で全子要素を必ず走査する。
                if (recurse(path, child, pending_files)) contains_scenario = true;
            }
            if (has_children) return contains_scenario;
        }
        pending_files[key].push_back(path_utf8(path));
        return false;
    };

    for (const auto& source : arg_paths) {
        FileBuckets pending_files;
        if (recurse(allparent, fs::u8path(source), pending_files)) {
            for (auto& [key, values] : pending_files) {
                auto& destination = files[key];
                destination.insert(destination.end(), values.begin(), values.end());
            }
        }
    }
    return {std::move(headers), std::move(files)};
}

bool to_scenarioheaders_recurse(::cw::lib::String arg_parent, ::cw::lib::String arg_path, std::map<std::tuple<::cw::lib::String, ::cw::lib::String>, std::vector<::cw::lib::String>> arg_notscenariofiles2)
{
    // Python の入れ子関数から生成された呼び出し側向けに、公開の
    // 互換ヘルパーとして残す。 同じ再帰的な存在確認を行うが、生成さ
    // れた宣言ではマップが値渡しなので、 収集したファイルが必要な呼
    // び出し側は to_scenarioheaders() を使う。
    namespace fs = std::filesystem;
    const fs::path path = fs::u8path(arg_path);
    const fs::path parent = fs::u8path(arg_parent);
    std::error_code ec;
    if (!storage_path_exists(path)) return false;
    if (::cw::scenariodb::is_scenario(path_utf8(path))) return true;
    if (!storage_path_is_directory(path)) {
        const auto relative = path_utf8(fs::relative(parent, parent, ec));
        (void)relative;
        arg_notscenariofiles2[{path_utf8(parent), {}}].push_back(path_utf8(path));
        return false;
    }
    bool found = false;
    bool has_children = false;
    std::vector<fs::path> children;
    if(::cardwirth::platform::is_mounted_user_path(path)) {
        const auto entries=::cardwirth::platform::list_mounted_user_path(path,true);
        if(!entries) throw std::runtime_error("cannot enumerate scenario directory");
        for(const auto& entry:*entries)children.push_back(path/entry.path.filename());
    } else for(const auto& entry:fs::directory_iterator(path))children.push_back(entry.path());
    for (const auto& child:children) {
        has_children = true;
        found = to_scenarioheaders_recurse(path_utf8(path), path_utf8(child), arg_notscenariofiles2) || found;
    }
    if (!has_children) arg_notscenariofiles2[{path_utf8(parent), {}}].push_back(path_utf8(path));
    return found;
}

::cw::lib::String create_dir(std::shared_ptr<::cw::dialog::scenarioinstall::ScenarioInstall> arg_parentdialog, ::cw::lib::String arg_dpath, const DirectoryNameInput& arg_input)
{
    (void)arg_parentdialog;
    play_ui_sound("signal");
    arg_dpath = linktarget_or_self(std::move(arg_dpath));
    std::filesystem::path base = std::filesystem::u8path(arg_dpath);
    auto display_name=path_utf8(fs::u8path(arg_dpath).filename());
    auto lowered_display_name=display_name;
    std::transform(lowered_display_name.begin(),lowered_display_name.end(),
                   lowered_display_name.begin(),
                   [](unsigned char c){return static_cast<char>(std::tolower(c));});
    if(lowered_display_name.ends_with(".lnk"))
        display_name.resize(display_name.size()-4);
    const auto default_path=fs::u8path(::cw::util::dupcheck_plus(
        // 共通の UTF-8 名は、明示的に UTF-8 として filesystem::path へ渡す
        // 。 Windows の通常の狭文字列コンストラクターは ACP を使うため、そのまま渡さない。
        path_utf8(base/fs::u8path("新規フォルダ")),false,true));
    const auto default_name=path_utf8(default_path.filename());
    const auto prompt=display_name+"に作成する新しいフォルダの名前を入力してください。";
    const auto chosen=arg_input ? arg_input(prompt,default_name)
        : ::cw::dialog::edit::show_common_modal_text_input(
            "新規フォルダ",prompt,default_name,255);
    if(!chosen)return {};
    auto candidate=fs::u8path(::cw::util::dupcheck_plus(
        ::cw::util::join_paths({path_utf8(base),*chosen}),false,true));
    if(::cardwirth::platform::is_mounted_user_path(candidate)) {
        if (!::cardwirth::platform::make_mounted_user_directory(candidate,true))
            throw std::runtime_error("Cannot create scenario directory");
    } else if (!std::filesystem::create_directories(candidate)) {
        throw std::filesystem::filesystem_error("Scenario directory already exists",candidate,
            std::make_error_code(std::errc::file_exists));
    }
    return path_utf8(candidate);
}

void InstallThread::initialize_typed(HeaderBuckets arg_headers, FileBuckets arg_notscenariofiles,
                                     ::cw::lib::String arg_dstpath,
                                     std::map<::cw::lib::String, std::vector<::cw::lib::String>> arg_db_repls,
                                     std::shared_ptr<::cw::scenariodb::Scenariodb> arg_db,
                                     ::cw::lib::String arg_skintype)
{
    m_headers = std::move(arg_headers);
    m_notscenariofiles = std::move(arg_notscenariofiles);
    m_dstpath = linktarget_or_self(std::move(arg_dstpath));
    m_db_repls = std::move(arg_db_repls);
    m_db = std::move(arg_db);
    m_skintype = std::move(arg_skintype);
    m_msg.clear();
    m_error.clear();
    m_num = 0;
    m_failed.reset();
    m_cancelled = false;
    m_updates.clear();
    m_paths.clear();
    m_filepaths.clear();
    m_source_links.clear();
    m_repl_links.clear();
    m_allret.reset();
    m_finished.store(false);
}

void InstallThread::run_typed()
{
    struct Completion {
        std::atomic_bool& finished;
        ~Completion() { finished.store(true); }
    } completion{m_finished};
    m_finished.store(false);
    const fs::path destination = fs::u8path(m_dstpath);
    if (m_dstpath.empty()) {
        m_error = "インストール先が指定されていません。";
        return;
    }
    try {
        for (const auto& [key, headers] : m_headers) {
            if (m_cancelled.load()) break;
            const auto& parent = std::get<1>(key);
            for (const auto& header : headers) {
                if (!install_header(*this, parent, header, destination)) {
                    // キャンセルでコピーを止めても、下の Py と
                    // 同じ元ディレクトリーの後処理には進む。 失敗
                    // したグループは打ち切り、次のグループと補助
                    // ファイルを試す。ワーカー全体は中断しない。
                    break;
                }
            }
        }
        if (m_install_notscenariofiles) {
            for (const auto& [key, files] : m_notscenariofiles) {
                if (m_cancelled.load()) break;
                const auto& parent = std::get<1>(key);
                for (const auto& file : files) {
                    if (!install_file(*this, parent, file, destination)) {
                        break;
                    }
                }
            }
        }
        if (m_delete_sourceafterinstalled) {
            for (const auto& [key, unused] : m_headers) {
                (void)unused;
                const auto& source_parent = std::get<0>(key);
                const auto& relative = std::get<1>(key);
                if (!relative.empty() && relative != "." &&
                    relative.rfind(::cw::lib::String("..") + static_cast<char>(fs::path::preferred_separator), 0) != 0)
                    ::cw::util::remove_emptydir(source_parent);
            }
        }
    } catch (const std::exception& error) {
        m_error = error.what();
    }
}

std::tuple<bool, std::vector<::cw::lib::String>, std::vector<::cw::lib::String>, bool> install_scenario(std::shared_ptr<::cw::dialog::scenarioinstall::ScenarioInstall> arg_parentdialog, HeaderBuckets arg_headers, FileBuckets arg_notscenariofiles, ::cw::lib::String arg_scedir, ::cw::lib::String arg_dstpath, std::shared_ptr<::cw::scenariodb::Scenariodb> arg_db, ::cw::lib::String arg_skintype)
{
    (void)arg_scedir;
    const auto destination = linktarget_or_self(std::move(arg_dstpath));
    if (destination.empty()) return {true, {}, {}, false};
    // 二つのインストール呼び出し側で、同じ上書きダイアログとワーカーを使う。
    std::map<::cw::lib::String, std::vector<::cw::lib::String>> db_repls;
    std::map<::cw::lib::String, std::vector<::cw::lib::String>> db_exists;
    std::map<::cw::lib::String,::cw::lib::String> overwrite_labels;
    std::vector<::cw::lib::String> source_links;
    if (arg_db) {
        for (const auto& [unused, headers] : arg_headers) {
            (void)unused;
            for (const auto& header : headers) {
                if (!header) continue;
                const auto existing = arg_db->find_scenario(value_string(header->m_name), value_string(header->m_author),
                                                            arg_skintype, header->m_dpath, header->m_fname);
                std::vector<::cw::lib::String> replaceable;
                for (const auto& old : existing) {
                    if (!old) continue;
                    const auto old_path = old->get_fpath();
                    auto extension = fs::u8path(old_path).extension().generic_string();
                    std::transform(extension.begin(), extension.end(), extension.begin(), [](unsigned char c) {
                        return static_cast<char>(std::tolower(c));
                    });
                    // Python と同様、既存の Windows ショートカット
                    // を置き換え一覧から除外し、インストール後に参照先を更新する。
#ifdef _WIN32
                    if (extension == ".lnk" && fs::is_regular_file(fs::u8path(old_path))) {
                        source_links.push_back(old_path);
                        continue;
                    }
#endif
                    replaceable.push_back(old_path);
                }
                if (replaceable.empty()) continue;
                db_exists[header->get_fpath()] = std::move(replaceable);
                overwrite_labels[header->get_fpath()]=header_label(header);
            }
        }
    }
    if (!db_exists.empty()) {
        ::cw::lib::String overwrite_message;
        if(db_exists.size()>1)
            overwrite_message=std::to_string(db_exists.size())+"本のシナリオがすでにインストール済みです。";
        else {
            const auto it=overwrite_labels.find(db_exists.begin()->first);
            const auto label=it==overwrite_labels.end()
                ? path_utf8(fs::u8path(db_exists.begin()->first).filename()) : it->second;
            overwrite_message="インストール済みの「"+label+
                "」がシナリオデータベース上に見つかりました。";
        }
        overwrite_message+="以前インストールしたシナリオを置換する場合は、置換対象をチェックしてください。";
        for(const auto&[source,paths]:db_exists)
            if(paths.size()>1){
                overwrite_message+="\n同一のシナリオを複数チェックした場合は、最初の1件が置換され、残りは削除されます。";
                break;
            }
        auto overwrite = std::make_shared<OverwriteScenarioDialog>();
        overwrite->initialize_rows(arg_scedir, overwrite_message, db_exists,
                                   overwrite_labels);
        if (!::cw::dialog::show_common_modal_presentation(overwrite) ||
            !overwrite->m_accepted)
            return {true, {}, {}, true};
        db_repls = overwrite->m_db_repls;
    }

    auto worker = std::make_shared<InstallThread>();
    worker->initialize_typed(std::move(arg_headers), std::move(arg_notscenariofiles), destination,
                             std::move(db_repls), std::move(arg_db), std::move(arg_skintype));
    std::shared_ptr<::cw::frame::Frame> install_frame;
    if (::cw::g_cwpy) {
        const auto* object = std::get_if<::cw::lib::ObjectPtr>(
            &::cw::g_cwpy->m_frame.storage());
        const auto frame = object && *object
            ? std::dynamic_pointer_cast<::cw::frame::Frame>(*object) : nullptr;
        install_frame=frame;
        if (frame) {
            worker->m_overwrite_callback = [weak_frame=std::weak_ptr<::cw::frame::Frame>(frame)](
                const ::cw::lib::Arguments& args,
                const ::cw::lib::KeywordArguments&) {
                const auto path = args.empty() ? ::cw::lib::String{} : value_string(args.front());
                const auto detail = args.size() < 2 ? ::cw::lib::String{} : value_string(args[1]);
                const auto frame_locked = weak_frame.lock();
                if (!frame_locked) return ::cw::lib::Value(static_cast<::cw::lib::Integer>(-1));
                return frame_locked->sync_exec([
                    path, detail](const ::cw::lib::Arguments&,
                                  const ::cw::lib::KeywordArguments&) {
                    return ::cw::lib::Value(show_common_overwrite_choice(path, detail));
                });
            };
        }
    } else if (arg_parentdialog) {
        worker->m_overwrite_callback = arg_parentdialog->m_overwrite_callback;
    }
    if (!worker->m_overwrite_callback) {
        worker->m_overwrite_callback = [](const ::cw::lib::Arguments& args, const ::cw::lib::KeywordArguments&) {
            const auto path = args.empty() ? ::cw::lib::String{} : value_string(args.front());
            const auto message = args.size() < 2 ? ::cw::lib::String{} : value_string(args[1]);
            return ::cw::lib::Value(show_common_overwrite_choice(path, message));
        };
    }
    worker->m_source_links = std::move(source_links);
    if (::cw::g_cwpy && ::cw::g_cwpy->m_setting) {
        worker->m_delete_sourceafterinstalled = ::cw::g_cwpy->m_setting->m_delete_sourceafterinstalled;
        worker->m_install_notscenariofiles = ::cw::g_cwpy->m_setting->m_install_notscenariofiles;
    }
    for (const auto& [unused, headers] : worker->m_headers) {
        (void)unused;
        worker->m_total += static_cast<::cw::lib::Integer>(headers.size());
    }
    if (worker->m_install_notscenariofiles) {
        for (const auto& [unused, files] : worker->m_notscenariofiles) {
            (void)unused;
            worker->m_total += static_cast<::cw::lib::Integer>(files.size());
        }
    }
    worker->m_finished.store(false);
    auto progress = std::make_shared<::cw::dialog::progress::ProgressDialog>();
    auto parent = arg_parentdialog
        ? std::static_pointer_cast<::cw::lib::Window>(arg_parentdialog)
        : std::make_shared<::cw::lib::Window>();
    progress->initialize(parent, "シナリオのインストール", {},
                         worker->m_total, 0, true, 400);
    worker->m_progress_dialog = progress;
    std::atomic_bool worker_started{false};
    progress->set_modal_callbacks(
        [worker,&worker_started] {
            bool expected=false;
            if (worker_started.compare_exchange_strong(expected,true)) {
                // 共通のタスク実行処理に合わせ、最初の確認すら行えな
                // いホストではバックグラウンドのインストールを開始し
                // ない。 初回確認では必ず表示を維持し、非常に速く成
                // 功したインストールを失敗と誤認しないようにする。
                try {
                    worker->worker=std::thread([worker] { worker->run_typed(); });
                } catch (const std::exception& error) {
                    worker->m_error=error.what();
                    worker->m_finished.store(true,std::memory_order_release);
                } catch (...) {
                    worker->m_error="インストール処理を開始できませんでした。";
                    worker->m_finished.store(true,std::memory_order_release);
                }
                return false;
            }
            return worker->m_finished.load(std::memory_order_acquire);
        },
        [worker] { worker->m_cancelled.store(true); });
    const bool shown=::cw::dialog::show_common_modal_presentation(progress);
    if(!shown) {
        worker->m_cancelled.store(true);
        // モーダルホストが失敗しても、UI スレッドで直ちにワーカーの終了待ちを
        // 行わない。 インストーラーが Frame::sync_exec で上書
        // きの判断を待っている場合があるため、同じ UI のメッセージ処理を続
        // けながら終了させる。 確認は安全側の失敗またはキャンセルとして戻る。
        while (worker_started.load(std::memory_order_acquire) &&
               !worker->m_finished.load(std::memory_order_acquire)) {
            ::cw::dialog::pump_all_mode_events();
            if (install_frame) {
                install_frame->drain_present_queue();
                install_frame->OnEXECFUNC(nullptr);
            }
            std::this_thread::yield();
        }
    }
    if(worker->worker.joinable())worker->worker.join();
    progress->set_modal_callbacks({},{});
    worker->m_progress_dialog.reset();
    progress->close();
    const bool failed_header=worker->m_failed&&*worker->m_failed;
    // ErrorMessage は空の名前も含め failed.name を
    // そのまま使う。 シナリオ選択ラベル用の作者名や無名の装飾は付けない。
    const auto failed_name=failed_header
        ? value_string((*worker->m_failed)->m_name) : ::cw::lib::String{};
    if(arg_parentdialog) arg_parentdialog->m_failed_name=failed_name;
    if (worker->m_failed.has_value() || !worker->m_error.empty()) {
        // 二つのインストール呼び出し側で、一つの共通エラー通知を使う。 補
        // 助処理・OS の失敗には ScenarioHeader がない場
        // 合もあるため、無関係なシナリオに結び付けず診断情報を維持する。
        const auto message=!failed_header
            ? "シナリオのインストールに失敗しました。\n"+worker->m_error
            : "「"+failed_name+"」のインストールに失敗しました。";
        // Py と同様、ここでエラー音と翻訳済みタイトルを含む ErrorMessage
        // を作る。 共通 Message の表示・入力経路を維持する。
        auto error_dialog = std::make_shared<::cw::dialog::message::ErrorMessage>();
        error_dialog->initialize(arg_parentdialog, message);
        (void)::cw::dialog::show_common_modal_presentation(error_dialog);
    }
    update_source_shortcuts(worker->m_source_links, worker->m_repl_links);
    if (!worker->m_failed && worker->m_error.empty() && !worker->m_paths.empty() && worker->m_db) {
        for (const auto& dpath : worker->m_updates)
            if (!dpath.empty()) worker->m_db->update(dpath,worker->m_skintype,true,true);
    }
    // Py はワーカー実行中の進捗キャンセルを dlg.cancel で表すが、モー
    // ダル完了後は cancelled=False を返す。 呼び出し側はその後に
    // 保存・終了し、反映済み項目を保持する。ネイティブのモーダルホストが利用できな
    // い場合は、 呼び出し自体をキャンセルとして、安全側で終了する境界を維持する。
    return {worker->m_failed.has_value() || !worker->m_error.empty(), std::move(worker->m_paths),
            std::move(worker->m_filepaths), !shown};
}

void InstallThread_install_scenario___init__(::cw::lib::Value arg_self, std::map<std::tuple<::cw::lib::String, ::cw::lib::String>, std::vector<std::shared_ptr<::cw::header::ScenarioHeader>>> arg_headers, std::map<std::tuple<::cw::lib::String, ::cw::lib::String>, std::vector<::cw::lib::String>> arg_notscenariofiles, ::cw::lib::String arg_dstpath, std::map<::cw::lib::String, std::vector<::cw::lib::String>> arg_db_repls)
{
    const auto worker = as_install_thread(arg_self);
    if (!worker) return;
    worker->initialize_typed(std::move(arg_headers), std::move(arg_notscenariofiles), std::move(arg_dstpath),
                             std::move(arg_db_repls), nullptr, {});
    if (!worker->m_overwrite_callback) {
        worker->m_overwrite_callback = [](const ::cw::lib::Arguments& args, const ::cw::lib::KeywordArguments&) {
            const auto path = args.empty() ? ::cw::lib::String{} : value_string(args.front());
            return ::cw::lib::Value(show_common_overwrite_choice(path, {}));
        };
    }
    if (::cw::g_cwpy && ::cw::g_cwpy->m_setting) {
        worker->m_delete_sourceafterinstalled = ::cw::g_cwpy->m_setting->m_delete_sourceafterinstalled;
        worker->m_install_notscenariofiles = ::cw::g_cwpy->m_setting->m_install_notscenariofiles;
    }
}

void InstallThread_install_scenario_run(::cw::lib::Value arg_self)
{
    if (const auto worker = as_install_thread(arg_self)) worker->run_typed();
}

::cw::lib::Integer InstallThread_install_scenario__confirm_overwrite(::cw::lib::Value arg_self, std::shared_ptr<::cw::dialog::progress::ProgressDialog> arg_dlg, ::cw::lib::String arg_s, std::vector<std::optional<::cw::lib::Integer>> arg_allret)
{
    (void)arg_dlg;
    const auto worker = as_install_thread(arg_self);
    if (!worker) return -1;
    if (!arg_allret.empty() && arg_allret.front().has_value()) return *arg_allret.front();
    return show_common_overwrite_choice(arg_s, "既存ファイルを置換しますか？");
}

::cw::lib::Integer InstallThread_install_scenario__confirm_overwrite_func()
{
    return show_common_overwrite_choice({}, "既存ファイルを置換しますか？");
}

void InstallThread_install_scenario__install(::cw::lib::Value arg_self, ::cw::lib::String arg_parent, std::vector<std::shared_ptr<::cw::header::ScenarioHeader>> arg_headers_seq, ::cw::lib::String arg_dstpath, std::vector<std::optional<::cw::lib::Integer>> arg_allret)
{
    const auto worker = as_install_thread(arg_self);
    if (!worker) return;
    const fs::path destination = fs::u8path(linktarget_or_self(std::move(arg_dstpath)));
    for (const auto& header : arg_headers_seq) if (!install_header(*worker, arg_parent, header, destination)) break;
    (void)arg_allret;
}

void InstallThread_install_scenario__install_files(::cw::lib::Value arg_self, ::cw::lib::String arg_parent, std::vector<::cw::lib::String> arg_files_seq, ::cw::lib::String arg_dstpath, std::vector<std::optional<::cw::lib::Integer>> arg_allret)
{
    const auto worker = as_install_thread(arg_self);
    if (!worker) return;
    const fs::path destination = fs::u8path(linktarget_or_self(std::move(arg_dstpath)));
    for (const auto& file : arg_files_seq) if (!install_file(*worker, arg_parent, file, destination)) break;
    (void)arg_allret;
}

void install_scenario_progress()
{
    // 互換用の進捗フックとして、呼び出しスレ
    // ッドの実行機会を他のスレッドへ譲る。
    std::this_thread::yield();
}

void update_scenariolog(::cw::lib::String arg_normpath, ::cw::lib::String arg_dst, bool arg_dstisfile)
{
    if (arg_normpath.empty() || arg_dst.empty() || same_or_normalized(arg_normpath, arg_dst)) return;
    const auto summary_or_xml_parent = [](const ::cw::lib::String& path) {
        const auto filename = path_utf8(fs::u8path(path).filename());
        ::cw::lib::String lowered = filename;
        std::transform(lowered.begin(), lowered.end(), lowered.begin(), [](unsigned char c) {
            return static_cast<char>(std::tolower(c));
        });
        if (lowered == "summary.wsm" || lowered == "summary.xml")
            return path_utf8(fs::u8path(path).parent_path());
        return path;
    };
    if (!::cw::g_cwpy) return;
    if (::cw::g_cwpy->m_setting) {
        auto& setting = *::cw::g_cwpy->m_setting;
        if (same_or_normalized(setting.m_lastscenariopath, arg_normpath)) {
            setting.m_lastscenario.clear();
            setting.m_lastscenariopath = arg_dst;
        }
        for (auto& path : setting.m_lastfindresult)
            if (same_or_normalized(path, arg_normpath)) path = arg_dst;
        for (auto& [path, name] : setting.m_bookmarks_for_cardedit)
            if (same_or_normalized(summary_or_xml_parent(path), arg_normpath)) path = arg_dst;
    }
    if (!::cw::g_cwpy->m_ydata || !*::cw::g_cwpy->m_ydata) return;
    const auto yado = *::cw::g_cwpy->m_ydata;
    for (auto& [spaths, path] : yado->m_bookmarks) {
        if (same_or_normalized(summary_or_xml_parent(path), arg_normpath)) {
            yado->changed();
            spaths.clear();
            path = arg_dst;
        }
    }
    if (::cw::g_cwpy->is_playingscenario()) {
        if (const auto* object = std::get_if<::cw::lib::ObjectPtr>(&::cw::g_cwpy->m_sdata.storage()); object && *object) {
            if (const auto sdata = std::dynamic_pointer_cast<::cw::data::SystemData>(*object))
                sdata->update_scenariopath(arg_normpath, arg_dst, arg_dstisfile);
        }
    }
    if (!arg_dstisfile)
        ::cw::sprite::message::update_scenariopath_for_log(arg_normpath, arg_dst);
    // Py と同様、finally の後処理も含め全アーカイブの処理を完了してから、現在のパーテ
    // ィー・履歴・カードのパスを変更する。 アーカイブに失敗した場合は、それらの更新を行わない。
    update_party_archive_logs(yado, arg_normpath, arg_dst);
    if (yado->m_party && *yado->m_party) {
        auto& party = *yado->m_party;
        if (same_or_normalized(value_string(party->m_lastscenariopath), arg_normpath)) {
            party->m_lastscenario.clear();
            party->m_lastscenariopath = arg_dst;
        }
    }
    if (arg_dstisfile) {
        if (yado->m_recenthistory)
            yado->m_recenthistory->update_scenariopath(arg_normpath, arg_dst);
    } else if (yado->m_party && *yado->m_party) {
        for (const auto& card : (*yado->m_party)->get_allcardheaders())
            if (card && card->m_scenariocard) card->update_scenariopath(arg_normpath, arg_dst);
    }
    // ネイティブ版では、出力先ファイルの隣に直接展開されたログも扱う。 Py と
    // 同じアーカイブ・パーティー・カードの処理順の後に、この拡張動作を維持する。
    if (!arg_dstisfile) update_log_xml(arg_normpath, arg_dst);
    if (::cw::g_fsync) ::cw::g_fsync->sync();
}

void update_scenariolog2(::cw::lib::String arg_normpath, ::cw::lib::String arg_dst, bool arg_dstisfile)
{
    if (arg_normpath.empty() || arg_dst.empty()) return;
    if (!arg_dstisfile && ::cw::g_cwpy && ::cw::g_cwpy->is_playingscenario()) {
        if (const auto* object = std::get_if<::cw::lib::ObjectPtr>(&::cw::g_cwpy->m_sdata.storage()); object && *object) {
            if (const auto sdata = std::dynamic_pointer_cast<::cw::data::SystemData>(*object))
                sdata->update_scenariopath2(arg_normpath, arg_dst, arg_dstisfile);
        }
    }
    if (::cw::g_fsync) ::cw::g_fsync->sync();
}

::cw::lib::Integer OverwriteScenarioDialog__resize_extent_w(::cw::lib::String arg_s)
{
    return SelectScenarioDirectory__resize_extent_w(std::move(arg_s));
}

::cw::lib::String create_installdesc(std::vector<std::shared_ptr<::cw::header::ScenarioHeader>> arg_headers_seq)
{
    if (arg_headers_seq.empty()) return {};
    ::cw::lib::String name;
    if (arg_headers_seq.size() > 1) {
        name = std::to_string(arg_headers_seq.size()) + "本のシナリオ";
    } else {
        const auto header = arg_headers_seq.front();
        name = header ? value_string(header->m_name) : ::cw::lib::String{};
        if (name.empty()) name = "(無名のシナリオ)";
        if (header) {
            const auto author = value_string(header->m_author);
            if (!author.empty()) name += "(" + author + ")";
        }
        name = "「" + name + "」";
    }
    const bool delete_source = ::cw::g_cwpy && ::cw::g_cwpy->m_setting
        ? ::cw::g_cwpy->m_setting->m_delete_sourceafterinstalled : false;
    if (delete_source) {
        return name + "をコピーし、シナリオデータベースに登録します。\n"
            "インストール完了後のファイルを削除したい場合は、詳細設定の"
            "[シナリオ] > [詳細] > [シナリオのインストールに成功したら元ファイルを削除する]で"
            "設定を変更します。";
    }
    return name + "を移動し、シナリオデータベースに登録します。\n"
        "インストール完了後のファイルを削除したくない場合は、詳細設定の"
        "[シナリオ] > [詳細] > [シナリオのインストールに成功したら元ファイルを削除する]で"
        "設定を変更します。";
}

